import{_ as r,o as a,c as n,a3 as t}from"./chunks/framework.z_KJ15Ep.js";const c=JSON.parse('{"title":"Begriffe des Reportdesigners","description":"","frontmatter":{"title":"Begriffe des Reportdesigners","source_pageid":1581,"source_revision":6550},"headers":[],"relativePath":"reporting/reportdesigner/glossar-zum-reportdesigner.md","filePath":"reporting/reportdesigner/glossar-zum-reportdesigner.md"}'),i={name:"reporting/reportdesigner/glossar-zum-reportdesigner.md"};function o(l,e,s,h,u,d){return a(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="begriffe-des-reportdesigners" tabindex="-1">Begriffe des Reportdesigners <a class="header-anchor" href="#begriffe-des-reportdesigners" aria-label="Permalink to &quot;Begriffe des Reportdesigners&quot;">​</a></h1><p>Schlagen Sie Begriffe zu Reportbereichen, Elementen, Datenquellen und Programmierung nach. Die Erläuterungen sind nach Themen geordnet.</p><p>Dieses Glossar erklärt Begriffe, die im Zusammenhang mit dem Reportdesigner von <strong>SchILD-NRW 3</strong> verwendet werden. Die Begriffe sind nach Themenbereichen sortiert und innerhalb der Bereiche alphabetisch gelistet.</p><h2 id="bereiche-eines-reports" tabindex="-1">Bereiche eines Reports <a class="header-anchor" href="#bereiche-eines-reports" aria-label="Permalink to &quot;Bereiche eines Reports&quot;">​</a></h2><h3 id="detailbereich" tabindex="-1">Detailbereich <a class="header-anchor" href="#detailbereich" aria-label="Permalink to &quot;Detailbereich&quot;">​</a></h3><p>Bereich des Reports, der für jeden Datensatz einmal ausgegeben wird (z. B. pro Schüler eine Zeile). Kernbereich für Listen.</p><h3 id="fuß" tabindex="-1">Fuß <a class="header-anchor" href="#fuß" aria-label="Permalink to &quot;Fuß&quot;">​</a></h3><p>Unterer Bereich eines Reports. Kann pro Seite oder pro Gruppe erscheinen. Typische Inhalte: Seitenzahlen, Datum, Dokumentname.</p><h3 id="gruppenkopf" tabindex="-1">Gruppenkopf <a class="header-anchor" href="#gruppenkopf" aria-label="Permalink to &quot;Gruppenkopf&quot;">​</a></h3><p>Kopf einer Gruppe. Wird zu Beginn einer Gruppierung ausgegeben (z. B. „Klasse 5a“).</p><h3 id="gruppenfuß" tabindex="-1">Gruppenfuß <a class="header-anchor" href="#gruppenfuß" aria-label="Permalink to &quot;Gruppenfuß&quot;">​</a></h3><p>Fuß einer Gruppe. Wird am Ende einer Gruppierung ausgegeben.</p><h3 id="kopf" tabindex="-1">Kopf <a class="header-anchor" href="#kopf" aria-label="Permalink to &quot;Kopf&quot;">​</a></h3><p>Oberer Bereich eines Reports. Kann pro Seite oder pro Gruppe erscheinen. Typischer Ort für Schulköpfe.</p><h2 id="felder-und-elemente" tabindex="-1">Felder und Elemente <a class="header-anchor" href="#felder-und-elemente" aria-label="Permalink to &quot;Felder und Elemente&quot;">​</a></h2><h3 id="dbcalc" tabindex="-1">DBCalc <a class="header-anchor" href="#dbcalc" aria-label="Permalink to &quot;DBCalc&quot;">​</a></h3><p>Feld für Berechnungen, Zähler oder Summen. Kann pro Gruppe oder global zurückgesetzt werden.</p><h3 id="dbtext" tabindex="-1">DBText <a class="header-anchor" href="#dbtext" aria-label="Permalink to &quot;DBText&quot;">​</a></h3><p>Feld zur Ausgabe von Datenfeldern (z. B. Name, Geburtsdatum, Klasse).</p><h3 id="element" tabindex="-1">Element <a class="header-anchor" href="#element" aria-label="Permalink to &quot;Element&quot;">​</a></h3><p>Sammelbegriff für alle Bestandteile eines Reports, z. B. Linien, Textfelder, Datenfelder, Bilder oder Subreports.</p><h3 id="label" tabindex="-1">Label <a class="header-anchor" href="#label" aria-label="Permalink to &quot;Label&quot;">​</a></h3><p>Feld mit festem Text. Wird zur Beschriftung verwendet (z. B. „Name“ oder „Geburtsdatum“).</p><h3 id="linie" tabindex="-1">Linie <a class="header-anchor" href="#linie" aria-label="Permalink to &quot;Linie&quot;">​</a></h3><p>Element zur visuellen Trennung. Wird häufig zwischen Detailbereichen genutzt.</p><h3 id="richtext" tabindex="-1">RichText <a class="header-anchor" href="#richtext" aria-label="Permalink to &quot;RichText&quot;">​</a></h3><p>Textfeldtyp mit formatiertem Text. Ermöglicht Platzhalter wie <strong>$JAHRGANG$</strong> zur Laufzeit.</p><h3 id="statischer-subreport" tabindex="-1">Statischer Subreport <a class="header-anchor" href="#statischer-subreport" aria-label="Permalink to &quot;Statischer Subreport&quot;">​</a></h3><p>Eingebetteter Report, der in den Hauptreport kopiert wird und dort unabhängig weiter existiert.</p><h3 id="dynamischer-subreport" tabindex="-1">Dynamischer Subreport <a class="header-anchor" href="#dynamischer-subreport" aria-label="Permalink to &quot;Dynamischer Subreport&quot;">​</a></h3><p>Verknüpfter Report, der beim Generieren geladen wird. Änderungen wirken automatisch in allen Reports.</p><h3 id="systemvariable" tabindex="-1">Systemvariable <a class="header-anchor" href="#systemvariable" aria-label="Permalink to &quot;Systemvariable&quot;">​</a></h3><p>Vorgefertigte Variable wie <strong>Druckdatum</strong>, <strong>Dokumentname</strong> oder Seitenzahlen.</p><h2 id="daten-und-datenverarbeitung" tabindex="-1">Daten und Datenverarbeitung <a class="header-anchor" href="#daten-und-datenverarbeitung" aria-label="Permalink to &quot;Daten und Datenverarbeitung&quot;">​</a></h2><h3 id="datenfeld" tabindex="-1">Datenfeld <a class="header-anchor" href="#datenfeld" aria-label="Permalink to &quot;Datenfeld&quot;">​</a></h3><p>In einer Datenquelle enthaltenes Feld (z. B. <strong>NameVorname</strong>, <strong>GebDat</strong>).</p><h3 id="datenquelle" tabindex="-1">Datenquelle <a class="header-anchor" href="#datenquelle" aria-label="Permalink to &quot;Datenquelle&quot;">​</a></h3><p>Quelle der Daten (z. B. <strong>Schueler</strong>, <strong>Abschnitt</strong>, <strong>Faecher</strong>). Enthält mehrere Datenfelder.</p><h3 id="gruppe-gruppierung" tabindex="-1">Gruppe / Gruppierung <a class="header-anchor" href="#gruppe-gruppierung" aria-label="Permalink to &quot;Gruppe / Gruppierung&quot;">​</a></h3><p>Zusammenfassung von Datensätzen nach einem Merkmal (z. B. Klasse). Ermöglicht eigene Köpfe, Füße und Seitenwechsel.</p><h3 id="serienreport" tabindex="-1">Serienreport <a class="header-anchor" href="#serienreport" aria-label="Permalink to &quot;Serienreport&quot;">​</a></h3><p>Report, der für mehrere Datensätze erzeugt wird (z. B. ein Zeugnis pro Schüler).</p><h3 id="zahler" tabindex="-1">Zähler <a class="header-anchor" href="#zahler" aria-label="Permalink to &quot;Zähler&quot;">​</a></h3><p>Mechanismus zur Nummerierung, häufig über <strong>DBCalc</strong> implementiert.</p><h2 id="ansichten-und-bedienung" tabindex="-1">Ansichten und Bedienung <a class="header-anchor" href="#ansichten-und-bedienung" aria-label="Permalink to &quot;Ansichten und Bedienung&quot;">​</a></h2><h3 id="berechnungen" tabindex="-1">Berechnungen <a class="header-anchor" href="#berechnungen" aria-label="Permalink to &quot;Berechnungen&quot;">​</a></h3><p>Modus des Editors zur Hinterlegung von Object-Pascal-Code. Reagiert auf Ereignisse (Events).</p><h3 id="entwurf" tabindex="-1">Entwurf <a class="header-anchor" href="#entwurf" aria-label="Permalink to &quot;Entwurf&quot;">​</a></h3><p>Modus zur Bearbeitung von Layout und Feldern.</p><h3 id="vorschau" tabindex="-1">Vorschau <a class="header-anchor" href="#vorschau" aria-label="Permalink to &quot;Vorschau&quot;">​</a></h3><p>Modus zur Ansicht des fertigen Reports vor dem Druck.</p><h2 id="programmierung-und-laufzeit" tabindex="-1">Programmierung und Laufzeit <a class="header-anchor" href="#programmierung-und-laufzeit" aria-label="Permalink to &quot;Programmierung und Laufzeit&quot;">​</a></h2><h3 id="ereignis-und-event" tabindex="-1">Ereignis und Event <a class="header-anchor" href="#ereignis-und-event" aria-label="Permalink to &quot;Ereignis und Event&quot;">​</a></h3><p>Auslöser, zu dem Code ausgeführt wird (z. B. beim Drucken, beim Anzeigen oder zwischen Datensätzen).</p><h3 id="ongettext" tabindex="-1">OnGetText <a class="header-anchor" href="#ongettext" aria-label="Permalink to &quot;OnGetText&quot;">​</a></h3><p>Ereignis zur Manipulation des darzustellenden Textes.</p><h3 id="onprint" tabindex="-1">OnPrint <a class="header-anchor" href="#onprint" aria-label="Permalink to &quot;OnPrint&quot;">​</a></h3><p>Ereignis kurz vor der Ausgabe. Häufig genutzt zur Steuerung von Sichtbarkeit.</p><h3 id="rap-funktionen" tabindex="-1">RAP-Funktionen <a class="header-anchor" href="#rap-funktionen" aria-label="Permalink to &quot;RAP-Funktionen&quot;">​</a></h3><p>Erweiterungen für SchILD-NRW. Bieten Sonderlogik, z. B. für Abschluss- oder Abschnittsinformationen.</p><h3 id="variable" tabindex="-1">Variable <a class="header-anchor" href="#variable" aria-label="Permalink to &quot;Variable&quot;">​</a></h3><p>Wert, der im Modus „Berechnungen“ definiert und für Code verwendet werden kann.</p><h2 id="layout-und-gestaltung" tabindex="-1">Layout und Gestaltung <a class="header-anchor" href="#layout-und-gestaltung" aria-label="Permalink to &quot;Layout und Gestaltung&quot;">​</a></h2><h3 id="dehnen" tabindex="-1">Dehnen <a class="header-anchor" href="#dehnen" aria-label="Permalink to &quot;Dehnen&quot;">​</a></h3><p>Eigenschaft, die ein Element an die Höhe seines Inhalts anpasst.</p><h3 id="seitenwechsel" tabindex="-1">Seitenwechsel <a class="header-anchor" href="#seitenwechsel" aria-label="Permalink to &quot;Seitenwechsel&quot;">​</a></h3><p>Erzeugt eine neue Seite, z. B. bei Gruppen oder Datensatzwechseln.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Glossar_zum_Reportdesigner" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 6550.</p>',69)])])}const g=r(i,[["render",o]]);export{c as __pageData,g as default};
